package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.*;
class AcquiringSeasonRobotTest {
 @Test void fourMassesAcquireAndExit(){for(int y:new int[]{2024,2025,2026})for(double mass:(y==2025?new double[]{.498951607,.816466266}:new double[]{y==2024?.235:.215})){
  var a=SourceAcquisition.run(y,mass,0);assertTrue(a.eligible);assertEquals(0,a.q);assertEquals(0,a.v);assertEquals(0,a.residual,1e-12);
  var r=AcquiringSeasonRobot.run(a,12,0);assertNotNull(r.robot().mechanism());assertEquals(mass,r.robot().mechanism().mass());assertEquals(a.pitch,r.robot().mechanism().angle());assertEquals(a.elapsed+r.robot().absoluteExitTime(),r.globalExitTime());assertEquals(0,r.robot().mechanism().plant().feedEnergy());
  assertThrows(IllegalStateException.class,()->AcquiringSeasonRobot.run(a,12,0));
  System.out.println("ACQUIRE_EXIT year="+y+" mass="+mass+" volts=12 plan=1 terminalQ="+a.q+" terminalV="+a.v+" acquisitionTime="+a.elapsed+" sourceEnergy="+a.sourceEnergy+" potential="+a.potentialGain+" dragLoss="+a.guideLoss+" impactLoss="+a.impactLoss+" impulse="+a.impulse+" residual="+a.residual+" dockTime="+r.robot().dock().time()+" chassisX="+r.robot().dock().x()+" chassisY="+r.robot().dock().y()+" heading="+r.robot().dock().heading()+" angle="+r.robot().mechanism().angle()+" length="+r.robot().mechanism().length()+" radius="+r.robot().mechanism().radius()+" inertia="+r.robot().mechanism().inertia()+" duty="+r.robot().mechanism().commandedDuty()+" speed="+r.robot().mechanism().plant().speed()+" motorResidual="+r.robot().mechanism().plant().energyResidual()+" feedEnergy="+r.robot().mechanism().plant().feedEnergy()+" motorWork="+r.robot().mechanism().plant().motorWork()+" robotTime="+r.robot().absoluteExitTime()+" globalTime="+r.globalExitTime()+" exitX="+r.robot().exitX()+" exitY="+r.robot().exitY()+" exitZ="+r.robot().exitZ()+" vx="+r.robot().worldVx()+" vy="+r.robot().worldVy()+" vz="+r.robot().worldVz());
 }}
 @Test void failuresNeverInvokeRobot(){for(int y:new int[]{2024,2025,2026})for(double mass:(y==2025?new double[]{.498951607,.816466266}:new double[]{y==2024?.235:.215}))for(int f:new int[]{1,2,3,4,5}){var a=SourceAcquisition.run(y,mass,f);assertFalse(a.eligible);assertThrows(IllegalStateException.class,()->AcquiringSeasonRobot.run(a,12,0));assertEquals(0,a.residual,1e-12);}}
 @Test void dynamicsAndDriveFaults(){for(int y:new int[]{2024,2025,2026}){var a=SourceAcquisition.run(y,.5,0);double accel=9.80665*Math.sin(a.pitch)+.02/a.mass;assertEquals(a.q,-.02+.6*a.travelTime-.5*accel*a.travelTime*a.travelTime,1e-12);assertEquals(a.preImpactSpeed,.6-accel*a.travelTime,1e-12);assertEquals(a.impulse,-a.mass*a.preImpactSpeed,1e-12);for(int f:new int[]{1,2}){var r=AcquiringSeasonRobot.run(SourceAcquisition.run(y,.5,0),12,f);assertNull(r.robot().mechanism());assertTrue(Double.isNaN(r.globalExitTime()));}}}
 @Test void invalidInputsRejected(){assertTrue(SourceAcquisition.run(2025,.816466266,6).eligible);assertFalse(SourceAcquisition.run(2026,.215,6).eligible);assertThrows(IllegalArgumentException.class,()->SourceAcquisition.run(2023,.5,0));assertThrows(IllegalArgumentException.class,()->SourceAcquisition.run(2025,Double.NaN,0));assertThrows(IllegalArgumentException.class,()->AcquiringSeasonRobot.run(null,12,0));}
 @AfterAll static void binding()throws Exception{
  String token=System.getenv("FRC_ACQUIRE_RUN_ID"),output=System.getenv("FRC_ACQUIRE_RUNTIME");if(token==null&&output==null)return;assertNotNull(token);assertNotNull(output);var p=new java.util.Properties();p.setProperty("runId",token);
  for(String n:new String[]{"SeasonRobotPrototype","SeasonRobotPrototype$Dock","SeasonRobotPrototype$Run","AcquiringSeasonRobotTest","SourceAcquisition","SourceAcquisition$Retained","AcquiringSeasonRobot","AcquiringSeasonRobot$Run","IntegratedPregripPrototype","IntegratedPregripPrototype$Result","PregripSupervisor","PregripSupervisor$State","PregripSupervisor$Observation","PregripSupervisor$Output","PoweredGuidePlant","PoweredGuidePlant$Config","PoweredGuidePlant$Sample","SharedSupply","SharedSupply$Result"}){Class<?> c=Class.forName("org.agentfrc.lesson."+n);p.setProperty(n+"Sha256",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(c.getResourceAsStream(n+".class").readAllBytes())));}
  var c=edu.wpi.first.math.system.plant.DCMotor.class;p.setProperty("DCMotorSha256",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(c.getResourceAsStream("DCMotor.class").readAllBytes())));
  try(var out=java.nio.file.Files.newOutputStream(java.nio.file.Path.of(output),java.nio.file.StandardOpenOption.CREATE_NEW)){p.store(out,"Fresh ideal-drive season robot slice");}System.out.println("ACQUIRE_RUN_ID="+token);
 }
}
